function fillContent(p){const T=TPL[tplKey(p.type)],pr=presetFor(p.type),v=variantFor(p);p.title=p.title||p.name;p.description=T.about(p.name);p.items=generateSuggestedItems(p.type,p.name);p.sections=sectionsForLevel(p.level||"professional");p.reviews=p.reviews||[];p.visualVariant=v.id;Object.assign(p,{c1:pr.c1,c2:pr.c2,font:v.font,dark:v.dark,visualStyle:"auto",layoutVariant:v.hero,density:v.density,btn:v.shape,contentIsSuggested:true});const imgs=imagePlan(p.type,p.name+String(p.id||""),20);p.banner=imgs.shift()||relevantImage(p.type,"hero",p.name);p.gallery=imgs.splice(0,8);p.items.forEach((it,i)=>{it.img=imgs[i]||""});seedBusinessData(p);p.designProposals=makeDesignProposals(p);p.selectedDesign=0;applyDesignProposal(p,0);repairImageRepetition(p);}
function norm(p){if(typeof p.items==="string")p.items=p.items.split(/\n+/).filter(Boolean).map(l=>{const[m,...r]=l.split(/\s[—-]\s/);return{cat:"",name:m.trim(),price:r.join(" ").replace(/^R\$\s*/,""),desc:"",img:""}});if(p.type==="hairdresser")p.type=/barb/i.test(p.name||"")?"barber":"salon";const txt=[p.name,p.category,p.description].filter(Boolean).join(" ");if(/pet shop|agro pet|petshop|produtos pet/i.test(txt))p.type="pet";const pr=presetFor(p.type||"other"),v=variantFor(p);const out=Object.assign({title:p.name,description:"",items:[],gallery:[],reviews:[],banner:"",btn:v.shape,level:p.level||"professional",sections:sectionsForLevel(p.level||"professional"),published:false,c1:p.color||pr.c1,c2:pr.c2,font:v.font,dark:v.dark,visualStyle:"auto",layoutVariant:v.hero,density:v.density,visualVariant:v.id,contentIsSuggested:false,modules:defaultModules(p.type),staff:[],services:[],plans:[],classes:[],rooms:[],specialties:[],designProposals:null,selectedDesign:0,designImages:[]},p);ensureBusinessData(out);ensureDesignProposals(out);applyDesignProposal(out,out.selectedDesign);return repairImageRepetition(out)}
platforms=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(OLD_KEY)||localStorage.getItem("radarPlatformsV10")||localStorage.getItem("radarPlatformsV9")||localStorage.getItem("radarPlatformsV8")||localStorage.getItem("radarPlatformsV7")||"[]").map(norm); loadSales(); try{const saved=JSON.parse(localStorage.getItem("radarProspectionLocationV14")||"null");if(saved&&saved.lat&&saved.lon)here=saved}catch{}
function loadSales(){try{sales=JSON.parse(localStorage.getItem(SALES_KEY)||"[]");if(!Array.isArray(sales))sales=[]}catch{sales=[]}}
async function persistServerState(){
  try{const r=await fetch("/api/state",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({sales,platforms})});if(!r.ok)throw new Error("server-save-failed");serverSyncReady=true;return true}catch(e){serverSyncReady=false;return false}
}
async function syncServerState(){
  try{const r=await fetch("/api/state");if(!r.ok)return;const d=await r.json();if(!d?.state)return;const st=d.state;
    if(Array.isArray(st.sales)&&st.sales.length){const byId=new Map(sales.map(x=>[String(x.id),x]));st.sales.forEach(x=>byId.set(String(x.id),x));sales=[...byId.values()]}
    if(Array.isArray(st.platforms)&&st.platforms.length){const byId=new Map(platforms.map(x=>[String(x.id),x]));st.platforms.forEach(x=>byId.set(String(x.id),norm(x)));platforms=[...byId.values()]}
    localStorage.setItem(SALES_KEY,JSON.stringify(sales));localStorage.setItem(KEY,JSON.stringify(platforms));serverSyncReady=true;renderPlatforms();renderServiceCentral();renderSalesPipeline();await persistServerState();
  }catch(e){serverSyncReady=false;}
}
function saveSales(){localStorage.setItem(SALES_KEY,JSON.stringify(sales));renderSalesPipeline();persistServerState()}
function stageIndex(id){return Math.max(0,SALES_STAGES.findIndex(s=>s.id===id))}
function saleForBusiness(b){if(!b)return null;let x=sales.find(s=>String(s.businessId)===String(b.id)||String(s.name)===String(b.name));if(!x){x={id:crypto.randomUUID(),businessId:b.id,name:b.name,type:b.type,phone:b.phone,whatsapp:b.whatsapp,instagram:b.instagram,address:b.address,stage:"analyze",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),service:null,price:0,domain:"",paymentStatus:"pending",publishedUrl:"",notes:"",analysis:analyze(b)};sales.push(x);saveSales()}return x}
function advanceSale(id,next,extra={}){const x=sales.find(s=>String(s.id)===String(id));if(!x)return;x.stage=next;Object.assign(x,extra,{updatedAt:new Date().toISOString()});saveSales()}
function salePlatform(s){return platforms.find(p=>String(p.id)===String(s.platformId||s.businessId)||p.name===s.name)}
function beginGuidedFromResults(){guidedStartPending=false;if(!results.length){setStatus("Não encontrei empresas válidas nesta pesquisa. Tente ampliar o raio ou mudar a categoria.",true);return}const fresh=results.filter(b=>!sales.some(s=>s.name===b.name));const pool=fresh.length?fresh:results;const chosen=pool.slice().sort((a,b)=>analyze(b).score-analyze(a).score||a.distance-b.distance)[0];if(!chosen)return;const sale=saleForBusiness(chosen);sale.stage="analyze";sale.analysis=analyze(chosen);sale.selectedBusiness={id:chosen.id,name:chosen.name,type:chosen.type,phone:chosen.phone,whatsapp:chosen.whatsapp,instagram:chosen.instagram,address:chosen.address,distance:chosen.distance,website:chosen.website||""};sale.updatedAt=new Date().toISOString();saveSales();renderSalesPipeline();document.getElementById("salesPipeline")?.scrollIntoView({behavior:"smooth",block:"start"})}
