function money(v){v=String(v||"").trim();return v?(/^R\$/i.test(v)?v:"R$ "+v):""}
function siteCSS(p){const v=variantFor(p);const r={pill:"999px",round:"12px",square:"2px"}[p.btn||v.shape]||"999px";const dark=p.dark,accent=p.c1||"#d89b3d",second=p.c2||"#191919";const max=p.level==="complete"?1240:p.level==="professional"?1160:980;const gap=p.density==="compact"?12:18;const heroMin=v.id==="clean"?560:v.id==="bold"?700:650;const radius=v.id==="square"?2:v.id==="luxe"?24:14;return`*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:${dark?"#0b0b0d":"#f5f2ed"};color:${dark?"#f5f2ec":"#171717"}.site{--c1:${accent};--c2:${second};--surface:${dark?"#151518":"#fff"};--muted:${dark?"#b7b1a8":"#666"};font-family:${p.font},system-ui,sans-serif;line-height:1.55;min-height:100vh}.site *{box-sizing:border-box}.nav{position:sticky;top:0;z-index:10;background:${dark?"rgba(8,8,9,.86)":"rgba(255,255,255,.9)"};backdrop-filter:blur(14px);padding:15px clamp(18px,5vw,70px);display:flex;align-items:center;gap:22px;border-bottom:1px solid rgba(128,128,128,.18)}.nav a{color:${dark?"#fff":"#111"};text-decoration:none;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.05em}.nav .brand{margin-right:auto;font-size:19px;text-transform:none;letter-spacing:0}.nav .btn{color:#fff}.hero{min-height:${heroMin}px;display:flex;align-items:center;background-size:cover;background-position:center;color:#fff;position:relative}.hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.82),rgba(0,0,0,.38) 62%,rgba(0,0,0,.1))}.hero-content{position:relative;z-index:1;max-width:${max}px;width:100%;margin:auto;padding:80px clamp(20px,6vw,80px)}.hero.center{text-align:center;justify-content:center}.hero.center .hero-content{max-width:850px}.hero.editorial{align-items:flex-end}.hero h1{font-size:clamp(46px,7vw,92px);line-height:.94;letter-spacing:-.045em;margin:14px 0;max-width:900px}.hero p{font-size:clamp(15px,1.7vw,20px);max-width:680px;color:rgba(255,255,255,.85);margin:0 0 25px}.eyebrow{display:inline-block;text-transform:uppercase;letter-spacing:.18em;font-size:11px;color:${accent};font-weight:900}.hero-actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;background:${accent};color:#fff!important;padding:12px 20px;text-decoration:none;font-weight:900;border-radius:${r};margin:4px;border:1px solid transparent}.btn.o{background:transparent;border-color:rgba(255,255,255,.75)}.wrap{max-width:${max}px;margin:auto;padding:20px clamp(18px,4vw,45px) 80px}.site section{padding:65px 0}.site section.alt{background:${dark?"#111114":"#fff"};margin-left:-45px;margin-right:-45px;padding-left:45px;padding-right:45px}.site h2{font-size:clamp(30px,4vw,52px);line-height:1;letter-spacing:-.035em;margin:8px 0 25px}.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.18em;font-weight:900;color:${accent}}.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:${gap}px}.it{display:flex;gap:14px;padding:0;border:1px solid rgba(128,128,128,.15);background:${dark?"#151518":"#fff"};border-radius:${radius}px;overflow:hidden;margin:0}.it img{width:150px;height:150px;object-fit:cover}.it div{padding:16px;flex:1}.it small{opacity:.72}.pr{font-weight:900;color:${accent};white-space:nowrap;padding:16px}.gal{display:grid;grid-template-columns:1.4fr .8fr .8fr;grid-auto-rows:220px;gap:10px}.gal img{width:100%;height:100%;object-fit:cover;border-radius:12px}.gal img:first-child{grid-row:span 2}.rv,.feature,.faq{padding:22px;border-radius:15px;background:${dark?"#151518":"#fff"};border:1px solid rgba(128,128,128,.14);margin:0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.feature img{width:100%;aspect-ratio:1.1;object-fit:cover}.story{display:grid;grid-template-columns:1fr 1fr;gap:35px;align-items:center}.story img{width:100%;aspect-ratio:1.1;object-fit:cover;border-radius:16px}.promo{padding:35px;border-radius:18px;background:linear-gradient(110deg,${accent},${second});color:#fff;display:flex;align-items:center;justify-content:space-between;gap:20px}.promo h2{margin:0;color:#fff}.contact{display:grid;grid-template-columns:1fr 1fr;gap:25px;padding:35px;border-radius:18px;background:${second};color:#fff}.site footer{padding:45px clamp(20px,5vw,70px);background:${dark?"#050506":"#111"};color:#fff;display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:25px}.site footer h4{color:${accent};margin:0 0 8px}.site footer p,.site footer a{color:#aaa;font-size:12px}.wm{position:fixed;right:8px;bottom:8px;width:20px;height:20px;opacity:.25;pointer-events:none;border-radius:4px}.wordmark{font-weight:950;letter-spacing:-.045em;text-wrap:balance}.nav .wordmark{font-size:20px}.site a{text-underline-offset:3px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.story,.contact{grid-template-columns:1fr}.site section.alt{margin-left:-18px;margin-right:-18px;padding-left:18px;padding-right:18px}.site footer{grid-template-columns:1fr 1fr}}@media(max-width:620px){.nav a:not(.brand){display:none}.hero{min-height:590px}.hero h1{font-size:48px}.cards{grid-template-columns:1fr}.gal{grid-template-columns:1fr 1fr;grid-auto-rows:170px}.gal img:first-child{grid-row:span 1}.it{display:block}.it img{width:100%;height:180px}.contact,.site footer{grid-template-columns:1fr}.promo{display:block}}`}

function bookingSection(p){
 if(!moduleOn(p,"booking"))return "";
 const services=(p.services&&p.services.length?p.services:p.items||[]), staff=p.staff||[];
 return '<section id="agendamento" class="alt"><span class="kicker">Agendamento</span><h2>Escolha como você quer ser atendido.</h2><form class="booking-form" data-booking="1">'+
   '<select name="service" required><option value="">Escolha o serviço</option>'+services.map(function(x){return '<option>'+esc(x.name||"")+(x.price?' — '+esc(money(x.price)):"")+'</option>'}).join("")+'</select>'+
   '<select name="professional"><option value="">Qualquer profissional</option>'+staff.map(function(x){return '<option>'+esc(x.name||"")+'</option>'}).join("")+'</select>'+
   '<input name="date" type="date" required><select name="time" required><option value="">Horário preferido</option>'+["08:00","09:00","10:00","11:00","13:00","14:00","15:00","16:00","17:00","18:00"].map(function(x){return '<option>'+x+'</option>'}).join("")+'</select>'+
   '<button class="btn" type="submit">Solicitar agendamento</button></form><p class="micro">O pedido será enviado pelo WhatsApp. A confirmação final depende da disponibilidade real do estabelecimento.</p></section>';
}
function reservationSection(p){
 if(!moduleOn(p,"reservations"))return "";
 return '<section id="reserva"><div class="contact"><div><span class="kicker" style="color:#fff">Reservas</span><h2>Reserve sua mesa.</h2><p>Informe data, horário e quantidade de pessoas. A confirmação é feita pelo estabelecimento.</p></div>'+
   '<form class="booking-form" data-reservation="1"><input name="date" type="date" required><input name="time" type="time" required><input name="people" type="number" min="1" max="30" placeholder="Pessoas" required><button class="btn" type="submit">Solicitar reserva</button></form></div></section>';
}
function orderSection(p){
 if(!moduleOn(p,"orders")&&!moduleOn(p,"delivery"))return "";
 return '<section id="pedido"><div class="promo"><div><span class="kicker" style="color:#fff">Pedido</span><h2>Escolha um item e peça pelo WhatsApp.</h2><p>O Radar monta a mensagem automaticamente com o item escolhido.</p></div>'+
   (p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'" target="_blank">Abrir WhatsApp</a>':"")+'</div></section>';
}
function specializedSections(p){
 const k=p.type,out=[];
 if(["barber","salon","pet","car_repair"].includes(k))out.push(bookingSection(p));
 if(["restaurant","pizza"].includes(k))out.push(reservationSection(p));
 if(["restaurant","pizza","fast_food","cafe","bakery","shop","market","pet"].includes(k))out.push(orderSection(p));
 if(k==="gym"&&moduleOn(p,"plans"))out.push('<section id="planos"><span class="kicker">Planos</span><h2>Escolha seu plano.</h2><div class="cards">'+(p.plans||[]).map(function(x){return '<article class="feature"><h3>'+esc(x.name)+'</h3><strong class="pr">'+esc(money(x.price))+'</strong><p>'+esc(x.desc||"")+'</p>'+(p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'?text='+encodeURIComponent("Olá! Quero saber mais sobre o plano "+x.name+" da "+p.name+".")+'" target="_blank">Tenho interesse</a>':"")+'</article>'}).join("")+'</div></section>');
 if(k==="gym"&&moduleOn(p,"classes"))out.push('<section id="aulas" class="alt"><span class="kicker">Horários</span><h2>Aulas e modalidades</h2><div class="cards">'+(p.classes||[]).map(function(x){return '<article class="feature"><h3>'+esc(x.name)+'</h3><p>'+esc(x.days||"")+' '+esc(x.time||"")+'</p><small>'+esc(x.desc||"")+'</small></article>'}).join("")+'</div></section>');
 if(k==="clinic"&&moduleOn(p,"specialties"))out.push('<section id="especialidades"><span class="kicker">Atendimento</span><h2>Especialidades e serviços</h2><div class="cards">'+(p.specialties||[]).map(function(x){return '<article class="feature"><h3>'+esc(x.name)+'</h3><p>'+esc(x.desc||"")+'</p></article>'}).join("")+'</div></section>');
 if(k==="hotel"&&moduleOn(p,"rooms"))out.push('<section id="acomodacoes"><span class="kicker">Hospedagem</span><h2>Acomodações</h2><div class="cards">'+(p.rooms||[]).map(function(x){return '<article class="feature">'+(x.img?'<img src="'+esc(x.img)+'" alt="">':"")+'<h3>'+esc(x.name)+'</h3><strong class="pr">'+esc(money(x.price))+'</strong><p>'+esc(x.desc||"")+'</p></article>'}).join("")+'</div></section>');
 if(k==="car_repair"&&moduleOn(p,"quote"))out.push('<section id="orcamento" class="alt"><span class="kicker">Orçamento</span><h2>Conte o que seu veículo precisa.</h2><form class="booking-form" data-quote="1"><input name="vehicle" placeholder="Carro / moto / modelo" required><input name="service" placeholder="Serviço desejado" required><textarea name="details" placeholder="Descreva o problema"></textarea><button class="btn" type="submit">Pedir orçamento</button></form></section>');
 return out.join("");
}
function siteHTML(p){
 const T=TPL[tplKey(p.type)], enabled=new Set((p.sections||[]).filter(function(s){return s.on}).map(function(s){return s.k}));
 const primary=(p.designImages&&p.designImages.filter(Boolean).length?p.designImages:[]),imgs=(p.gallery&&p.gallery.filter(Boolean).length?p.gallery:RELEVANT_STOCK[tplKey(p.type)]||RELEVANT_STOCK.generic).filter(Boolean),visuals=(primary.length?primary:imgs);
 const layout=p.layoutVariant||"heroSplit", heroClass=layout==="heroCentered"?"center":layout==="editorial"?"editorial":"";
 const navKeys=["about","items","offers","gallery","team","reviews","faq","location","contact"].filter(function(k){return enabled.has(k)});
 const anchor=function(k){return k==="about"?"sobre":k==="items"?(T.kind.toLowerCase().includes("serv")?"servicos":"cardapio"):k};
 const extraNav=moduleOn(p,"booking")?'<a href="#agendamento">Agendar</a>':moduleOn(p,"reservations")?'<a href="#reserva">Reservar</a>':moduleOn(p,"orders")?'<a href="#pedido">Pedir</a>':"";
 const nav=p.level==="essential"?"":'<nav class="nav"><a class="brand wordmark" href="#top"><span>'+esc(p.name)+'</span></a>'+
   navKeys.slice(0,5).map(function(k){return '<a href="#'+anchor(k)+'">'+esc(SECTIONS[k])+'</a>'}).join("")+extraNav+
   (p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'" target="_blank">'+(["barber","salon","pet","car_repair"].includes(p.type)?"Agendar":"Pedir agora")+'</a>':"")+'</nav>';
 const cta=p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'" target="_blank">'+(["barber","salon","pet","car_repair"].includes(p.type)?"Falar / agendar pelo WhatsApp":"Pedir pelo WhatsApp")+'</a>':"";
 const bg=(p.banner||visuals[0])?' style="background-image:url(\''+esc(p.banner||imgs[0])+'\')"':"";
 const suggested=p.contentIsSuggested?'<div class="draft-note">Conteúdo inicial sugerido pelo Radar. Confirme informações, preços, horários e disponibilidade antes de publicar.</div>':"";
 const hero='<header class="hero '+heroClass+'"'+bg+'><div class="hero-content">'+suggested+'<span class="eyebrow">'+esc(labels[p.type]||"Estabelecimento")+' · Demonstração</span><h1>'+esc(p.title||p.name)+'</h1><p>'+esc(p.description||"")+'</p><div class="hero-actions">'+cta+(p.instagram?'<a class="btn o" href="'+esc(ig(p.instagram))+'" target="_blank">Instagram</a>':"")+'</div></div></header>';
 let body="";
 if(enabled.has("about")&&p.description)body+='<section id="sobre"><div class="story"><div><span class="kicker">Conheça</span><h2>Uma experiência feita para você.</h2><p>'+esc(p.description)+'</p>'+cta+'</div>'+(visuals[1]?'<img src="'+esc(visuals[1])+'" alt="">':"")+'</div></section>';
 if(enabled.has("items")&&p.items.length)body+='<section id="'+anchor("items")+'" class="alt"><span class="kicker">'+esc(T.kind)+'</span><h2>Veja nossas opções</h2><div class="menu-grid">'+p.items.slice(0,16).map(function(i){return '<article class="menu-item">'+(i.img?'<img src="'+esc(i.img)+'" alt="">':"")+'<div class="menu-body"><small>'+esc(i.cat||"Destaque")+'</small><h3>'+esc(i.name)+'</h3><p>'+esc(i.desc||"")+'</p><div class="item-bottom"><strong class="pr">'+esc(money(i.price))+'</strong>'+(moduleOn(p,"orders")&&p.whatsapp?'<button class="btn item-order" data-item="'+esc(i.name)+'">Pedir</button>':"")+'</div></div></article>'}).join("")+'</div></section>';
 if(enabled.has("offers"))body+='<section id="ofertas"><div class="promo"><div><span class="kicker" style="color:#fff">Oferta</span><h2>Destaques da semana</h2></div>'+cta+'</div></section>';
 if(moduleOn(p,"gallery")&&visuals.length)body+='<section id="galeria"><span class="kicker">Visual</span><h2>Galeria</h2><div class="gal">'+visuals.slice(0,6).map(function(x){return '<img src="'+esc(x)+'" alt="">' }).join("")+'</div></section>';
 if(moduleOn(p,"reviews")&&p.reviews.length)body+='<section id="avaliacoes"><span class="kicker">Confiança</span><h2>Avaliações</h2><div class="cards">'+p.reviews.slice(0,4).map(function(r){return '<div class="rv"><b style="color:var(--c1)">★★★★★</b><p>'+esc(r.text)+'</p><strong>— '+esc(r.name)+'</strong></div>'}).join("")+'</div></section>';
 if(enabled.has("faq"))body+='<section id="faq"><span class="kicker">Ajuda</span><h2>Perguntas frequentes</h2><div class="faq"><b>Como entrar em contato?</b><p>Use WhatsApp, telefone ou Instagram.</p></div><div class="faq"><b>Onde fica?</b><p>'+esc(p.address||"Consulte nosso contato.")+'</p></div></section>';
 if(moduleOn(p,"staff")&&p.staff.length)body+='<section id="equipe"><span class="kicker">Equipe</span><h2>Quem atende você</h2><div class="cards">'+p.staff.map(function(x){return '<article class="feature">'+(x.img?'<img src="'+esc(x.img)+'" alt="">':"")+'<h3>'+esc(x.name)+'</h3><p>'+esc(x.role||"")+'</p><small>'+esc(x.specialty||"")+'</small></article>'}).join("")+'</div></section>';
 if(enabled.has("location"))body+='<section id="localizacao"><div class="contact"><div><span class="kicker" style="color:#fff">Visite</span><h2>Estamos por aqui.</h2><p>'+esc(p.address||"Endereço não cadastrado")+'</p>'+(p.address?'<a class="btn" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.address)+'" target="_blank">Abrir no mapa</a>':"")+'</div><div><h3>Contato</h3><p>'+esc(p.phone||"")+'</p>'+cta+'</div></div></section>';
 if(enabled.has("contact"))body+='<section id="contato" class="alt"><div class="contact"><div><span class="kicker" style="color:#fff">Contato</span><h2>Vamos conversar?</h2><p>'+esc(p.address||"")+'</p></div><div>'+cta+(p.phone?'<a class="btn o" href="tel:'+esc(p.phone)+'">Ligar</a>':"")+'</div></div></section>';
 body+=specializedSections(p);
 const footer='<footer><div><h3>'+esc(p.name)+'</h3><p>'+esc(p.description||"")+'</p></div><div><h4>Contato</h4><p>'+esc(p.phone||"")+'</p><p>'+esc(p.address||"")+'</p></div><div><h4>Redes</h4>'+(p.instagram?'<p><a href="'+esc(ig(p.instagram))+'" target="_blank">Instagram</a></p>':"")+(p.whatsapp?'<p><a href="'+esc(wa(p.whatsapp))+'" target="_blank">WhatsApp</a></p>':"")+'</div><div><h4>Radar de Clientes</h4><p>Plataforma modular criada com o Radar de Clientes.</p></div></footer><img class="wm" src="'+esc(logoURL)+'" alt="">';
 return '<div class="site" id="top">'+nav+hero+'<main class="wrap">'+body+'</main>'+footer+'</div>';
}
const fullDoc=function(p){
 const name=String(p.name||"").replace(/[^\wÀ-ÿ ]/g,""), waNum=JSON.stringify(p.whatsapp||"");
 const script='<script>(function(){function go(msg){var n='+waNum+'.replace(/\\D/g,"");if(n.length===10||n.length===11)n="55"+n;if(!n){alert("WhatsApp do estabelecimento não está cadastrado.");return}location.href="https://wa.me/"+n+"?text="+encodeURIComponent(msg)}document.addEventListener("click",function(e){var b=e.target.closest("[data-item]");if(b)go("Olá! Gostaria de pedir: "+b.getAttribute("data-item")+". Negócio: '+name+'. ");});document.addEventListener("submit",function(e){var f=e.target;if(!f.matches("form"))return;e.preventDefault();var fd=new FormData(f),pairs=[];fd.forEach(function(v,k){if(v)pairs.push(k+": "+v)});go("Olá! Gostaria de solicitar atendimento para '+name+'.\\n"+pairs.join("\\n"));});})();<\\/script>';
 return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+esc(p.description||p.name)+'"><meta property="og:title" content="'+esc(p.title||p.name)+'"><meta property="og:description" content="'+esc(p.description||"")+'"><title>'+esc(p.title||p.name)+'</title><style>'+siteCSS(p)+'</style></head><body>'+siteHTML(p)+script+'</body></html>';
};

/* ---------- V14.2 Central de Serviços ---------- */
const SERVICE_MODULES={site:{icon:"🌐",name:"Site profissional",desc:"Site completo com o Designer original do Radar."},social:{icon:"📱",name:"Redes Sociais",desc:"Posts, Stories, bio, calendário e ideias adaptadas ao negócio."},whatsapp:{icon:"💬",name:"WhatsApp Business",desc:"Perfil, mensagens, respostas rápidas e menu de atendimento."},photos:{icon:"📸",name:"Fotos comerciais",desc:"Organização, corte e formatos comerciais para suas imagens."},catalog:{icon:"📋",name:"Catálogo / Cardápio",desc:"Produtos, serviços, categorias, preços e imagens."},booking:{icon:"📅",name:"Agendamento / Reservas",desc:"Base de agenda preparada para evolução futura."},marketing:{icon:"📈",name:"Marketing / CRM",desc:"Prospecção, leads, mensagens e acompanhamento."}};
const SERVICE_KEY="radarServiceProjectsV143";
const OLD_SERVICE_KEY="radarServiceProjectsV142";
function serviceProjects(){try{const now=JSON.parse(localStorage.getItem(SERVICE_KEY)||"[]");if(now.length)return now;const old=JSON.parse(localStorage.getItem(OLD_SERVICE_KEY)||"[]");if(old.length)localStorage.setItem(SERVICE_KEY,JSON.stringify(old));return old}catch{return[]}}
function saveServiceProject(x){const a=serviceProjects(),id=String(x.id||crypto.randomUUID());x.id=id;const i=a.findIndex(y=>String(y.id)===id);if(i<0)a.push(x);else a[i]={...a[i],...x,updatedAt:new Date().toISOString()};localStorage.setItem(SERVICE_KEY,JSON.stringify(a));const b=platforms.find(p=>String(p.id)===String(x.businessId)||p.name===x.name?.split(" · ")[0]);if(b){const sale=saleForBusiness(b);advanceSale(sale.id,"demo",{service:SERVICE_MODULES[x.module]?.name||x.module,businessId:b.id})}return x}
function currentBusinessForService(){return platforms[0]||results[0]||null}
function recommendedServices(p){if(!p)return[];const a=[];if(!p.whatsapp)a.push("whatsapp");if(!p.items?.length)a.push("catalog");if(!p.gallery?.length)a.push("photos");if(["barber","salon","pet","gym","clinic","hotel","car_repair"].includes(p.type))a.push("booking");a.push("marketing");return [...new Set(a)].slice(0,5)}
function renderServiceCentral(){const mount=$("serviceCentral");if(!mount)return;const a=serviceProjects();const list=a.slice().reverse().slice(0,20).map(x=>`<article class="saved-service"><div><span>${SERVICE_MODULES[x.module]?.icon||"📦"}</span><div><b>${esc(x.name)}</b><small>${esc(SERVICE_MODULES[x.module]?.name||x.module)} · ${new Date(x.createdAt).toLocaleDateString("pt-BR")}</small></div></div><div class="saved-service-actions"><button class="secondary" data-open-service="${x.id}">✏️ Editar</button><button class="secondary" data-preview-service="${x.id}">👁️ Prévia</button><button class="danger" data-delete-service="${x.id}">🗑️ Apagar</button></div></article>`).join("");mount.innerHTML=`<section class="panel service-central"><div class="section-head"><div><span class="eyebrow-ui">V14.3 · CENTRAL</span><h2>📦 Central de Projetos</h2><p>Os projetos salvos ficam aqui para editar ou apagar. Para criar um novo projeto, use o botão “Criar projeto” ao lado de “Confirmar e conversar” em cada negócio. Cada projeto salvo pode ser editado, pré-visualizado ou apagado aqui.</p></div></div><h3 class="saved-title">Projetos salvos</h3>${list||'<div class="empty">Nenhum projeto de serviço criado ainda.</div>'}</section>`}
function openService(key,business,saved){if(key==="site"){const b=business||currentBusinessForService();if(!b){alert("Pesquise ou selecione um negócio primeiro.");return}const existing=platforms.find(x=>x.id===b.id)||platforms.find(x=>x.name===b.name);if(existing)openEditor(existing,"adm");else createPlatform(b);return}const info=SERVICE_MODULES[key],p=business||currentBusinessForService(),modal=document.createElement("div");modal.className="service-modal";modal.innerHTML=serviceToolHTML(key,info,p);document.body.appendChild(modal);bindServiceTool(modal,key,p,saved)}
function serviceToolHTML(key,info,p){const ctx=p?`Negócio em foco: <b>${esc(p.name)}</b>`:"Nenhum negócio selecionado.";if(key==="social")return `<div class="service-box wide"><button class="close">×</button><span class="eyebrow-ui">V14.3 · REDES SOCIAIS</span><h2>${info.icon} ${info.name}</h2><div class="service-context">${ctx}</div><div class="tool-grid"><label>Rede<select id="smNetwork"><option>Instagram</option><option>Facebook</option><option>TikTok</option></select></label><label>Formato<select id="smFormat"><option>Post</option><option>Story</option><option>Reels</option></select></label><label>Objetivo<select id="smGoal"><option>Divulgação</option><option>Vendas</option><option>Engajamento</option><option>Apresentação</option><option>Promoção</option></select></label><label>Tom<select id="smTone"><option>Profissional</option><option>Descontraído</option><option>Premium</option><option>Direto para vendas</option></select></label><label>Tema<input id="smTopic" placeholder="Ex.: promoção de fim de semana"></label><label>Oferta/CTA<input id="smCta" placeholder="Ex.: peça pelo WhatsApp"></label></div><div class="actions"><button class="primary" data-generate-social>✨ Gerar conteúdo</button><button class="secondary" data-generate-calendar>📅 Gerar semana</button></div><label>Conteúdo gerado<textarea id="smResult" rows="12" placeholder="O conteúdo aparecerá aqui..."></textarea></label><h3>Perfil</h3><div class="tool-grid"><label>Bio<textarea id="smBio" rows="4" placeholder="Bio comercial..."></textarea></label><label>Destaques<textarea id="smHighlights" rows="4" placeholder="Ex.: Cardápio | Promoções | Endereço"></textarea></label></div><div class="actions"><button class="secondary" data-copy-result="smResult">📋 Copiar conteúdo</button><button class="secondary" data-copy-result="smBio">📋 Copiar bio</button><button class="primary" data-save-service>💾 Salvar projeto</button></div></div>`;
if(key==="whatsapp")return `<div class="service-box wide"><button class="close">×</button><span class="eyebrow-ui">V14.3 · WHATSAPP BUSINESS</span><h2>${info.icon} ${info.name}</h2><div class="service-context">${ctx}</div><div class="tool-grid">${inpStatic("waBusinessName","Nome",p?.name||"")}${inpStatic("waDescription","Descrição",p?.description||"")}${inpStatic("waHours","Horário","Ex.: Seg-Sáb 09h às 19h")}${inpStatic("waAddress","Endereço",p?.address||"")}${inpStatic("waCategory","Categoria",labels[p?.type]||"")}</div><h3>Mensagens automáticas</h3><div class="tool-grid"><label>Saudação<textarea id="waGreeting" rows="3">Olá! Seja bem-vindo(a) à ${esc(p?.name||"nossa empresa")}.</textarea></label><label>Ausência<textarea id="waAway" rows="3">No momento estamos fora do horário. Assim que possível responderemos.</textarea></label><label>Encerramento<textarea id="waClosing" rows="3">Obrigado pelo contato! Ficamos à disposição.</textarea></label><label>Resposta rápida<textarea id="waQuick" rows="3">Olá! Vou verificar isso para você.</textarea></label></div><h3>Menu de atendimento</h3><div class="tool-grid"><label>Opção 1<input id="waOpt1" value="Ver catálogo/cardápio"></label><label>Opção 2<input id="waOpt2" value="Agendar atendimento"></label><label>Opção 3<input id="waOpt3" value="Endereço e horário"></label><label>Opção 4<input id="waOpt4" value="Falar com atendente"></label></div><div class="actions"><button class="primary" data-generate-wa>✨ Montar configuração</button><button class="secondary" data-copy-result="waResult">📋 Copiar</button><button class="primary" data-save-service>💾 Salvar projeto</button></div><textarea id="waResult" rows="12" placeholder="A configuração aparecerá aqui..."></textarea></div>`;
if(key==="photos")return `<div class="service-box wide"><button class="close">×</button><span class="eyebrow-ui">V14.2 · FOTOS</span><h2>${info.icon} ${info.name}</h2><div class="service-context">${ctx}</div><p>As ferramentas desta primeira fase funcionam no navegador, sem alterar o arquivo original.</p><div class="actions"><button class="secondary" data-photo-upload>➕ Adicionar fotos</button><input id="photoInput" type="file" accept="image/*" multiple hidden></div><div id="photoPreview" class="photo-tool-grid"></div><div class="tool-grid"><label>Formato<select id="photoFormat"><option value="original">Original</option><option value="square">Quadrado 1:1</option><option value="post">Instagram 4:5</option><option value="story">Story 9:16</option><option value="banner">Banner 16:9</option></select></label><label>Raio<select id="photoRadius"><option value="0">Sem arredondar</option><option value="18">Arredondado</option><option value="999">Circular</option></select></label></div><div class="actions"><button class="primary" data-photo-apply>Aplicar formato</button><button class="primary" data-save-service>💾 Salvar projeto</button></div></div>`;
if(key==="catalog")return `<div class="service-box wide"><button class="close">×</button><span class="eyebrow-ui">V14.2 · CATÁLOGO</span><h2>${info.icon} ${info.name}</h2><div class="service-context">${ctx}</div><p class="draft-note">Itens iniciais podem ser sugestões. Confirme nomes, preços e informações antes de publicar.</p><div id="catalogRows"></div><div class="actions"><button class="secondary" data-add-catalog>➕ Adicionar item</button><button class="primary" data-save-catalog>💾 Salvar catálogo</button></div></div>`;
return `<div class="service-box wide"><button class="close">×</button><span class="eyebrow-ui">V14.2 · ${info.name.toUpperCase()}</span><h2>${info.icon} ${info.name}</h2><div class="service-context">${ctx}</div><p>Este módulo foi preparado como base local nesta versão. A agenda online compartilhada ficará para uma etapa posterior.</p><div class="tool-grid"><label>Horário de abertura<input id="bkOpen" value="09:00"></label><label>Horário de fechamento<input id="bkClose" value="19:00"></label><label>Duração padrão<input id="bkDuration" value="45 min"></label><label>Intervalo<input id="bkBreak" value="12:00–13:00"></label></div><div class="actions"><button class="primary" data-save-service>💾 Salvar configuração</button></div></div>`}
function inpStatic(id,label,value){return `<label>${label}<input id="${id}" value="${esc(value)}"></label>`}
function openServicePreview(id){const x=serviceProjects().find(y=>String(y.id)===String(id));if(!x)return;const d=x.data||{};$("servicePreviewTitle").textContent=(SERVICE_MODULES[x.module]?.icon||"📦")+" "+(x.name||"Prévia");let html="<div class='result-preview'>";
if(x.module==="social")html+=`<div class="preview-card"><h3>${esc(d.smNetwork||"Instagram")} · ${esc(d.smFormat||"Post")}</h3><p>${esc(d.smResult||"Nenhum conteúdo gerado ainda.").replace(/\n/g,"<br>")}</p></div><div class="preview-card"><h3>Bio</h3><p>${esc(d.smBio||"—").replace(/\n/g,"<br>")}</p><p><b>Destaques:</b> ${esc(d.smHighlights||"—")}</p></div>`;
else if(x.module==="whatsapp")html+=`<div class="preview-card"><h3>${esc(d.waBusinessName||"WhatsApp Business")}</h3><p>${esc(d.waDescription||"—")}</p><p><b>Horário:</b> ${esc(d.waHours||"—")}<br><b>Endereço:</b> ${esc(d.waAddress||"—")}</p></div><div class="preview-card"><h3>Menu</h3><ol>${[1,2,3,4].map(i=>d["waOpt"+i]).filter(Boolean).map(v=>`<li>${esc(v)}</li>`).join("")}</ol></div><div class="preview-card"><h3>Mensagens</h3><p>${esc(d.waResult||"Gere a configuração para ver o resultado.").replace(/\n/g,"<br>")}</p></div>`;
else if(x.module==="photos")html+=`<div class="preview-card"><p><b>Formato:</b> ${esc(d.photoFormat||"Original")}</p><div class="preview-photo-grid">${(d.photoImages||[]).map(u=>`<img src="${esc(u)}" alt="">`).join("")||"<div class='empty'>Nenhuma foto salva.</div>"}</div></div>`;
else if(x.module==="catalog")html+=`<div class="catalog-preview-grid">${(d.catalogItems||[]).map(i=>`<article class="preview-card">${i.img?`<img src="${esc(i.img)}" alt="">`:""}<small>${esc(i.cat||"Item")}</small><h3>${esc(i.name||"Sem nome")}</h3><p>${esc(i.desc||"")}</p><strong>${esc(i.price||"")}</strong></article>`).join("")||"<div class='empty'>Nenhum item salvo.</div>"}</div>`;
else html+=Object.entries(d).filter(([k,v])=>v).map(([k,v])=>`<div class="preview-card"><b>${esc(k)}</b><p>${esc(v).replace(/\n/g,"<br>")}</p></div>`).join("")||"<div class='empty'>Nenhum conteúdo salvo.</div>";
html+="</div>";$("servicePreviewBody").innerHTML=html;$("servicePreviewDialog").showModal()}
function bindServiceTool(modal,key,p,saved=null){modal.querySelector(".close").onclick=()=>modal.remove();if(key==="social"){modal.querySelector("[data-generate-social]").onclick=()=>{const n=p?.name||"seu negócio",topic=modal.querySelector("#smTopic").value||"apresentação do negócio",net=modal.querySelector("#smNetwork").value,fmt=modal.querySelector("#smFormat").value,tone=modal.querySelector("#smTone").value,goal=modal.querySelector("#smGoal").value,cta=modal.querySelector("#smCta").value||"Fale conosco e saiba mais";modal.querySelector("#smResult").value=`${fmt} · ${net} · ${goal}\n\n${n} — ${topic}.\nMostre ao público o que torna seu negócio especial e destaque uma informação real do estabelecimento.\n\nCTA: ${cta}.\n\n#${slug(n)} #${slug(topic)} #negociolocal`;const bio=modal.querySelector("#smBio");if(!bio.value)bio.value=`${n} | ${labels[p?.type]||"Negócio local"}\nProdutos e serviços para você.\n📍 ${p?.address||"Atendimento local"}\n💬 Fale conosco pelo WhatsApp.`;if(!modal.querySelector("#smHighlights").value)modal.querySelector("#smHighlights").value="Serviços | Produtos | Promoções | Endereço"};modal.querySelector("[data-generate-calendar]").onclick=()=>{const n=p?.name||"seu negócio",goal=modal.querySelector("#smGoal").value;const days=["Segunda","Terça","Quarta","Quinta","Sexta","Sábado","Domingo"];modal.querySelector("#smResult").value=days.map((d,i)=>`${d}: ${i===0?"Apresentação do negócio":i===1?"Produto/serviço em destaque":i===2?"Dica ou conteúdo educativo":i===3?"Bastidores/prova social":i===4?"Oferta ou chamada para WhatsApp":i===5?"Story com interação":"Resumo da semana"}\nObjetivo: ${goal}\nNegócio: ${n}`).join("\n\n")};}if(key==="whatsapp")modal.querySelector("[data-generate-wa]").onclick=()=>{const n=modal.querySelector("#waBusinessName").value||p?.name||"empresa";const opts=[1,2,3,4].map(i=>modal.querySelector(`#waOpt${i}`).value).filter(Boolean);const g=modal.querySelector("#waGreeting").value,a=modal.querySelector("#waAway").value,c=modal.querySelector("#waClosing").value,q=modal.querySelector("#waQuick").value;modal.querySelector("#waResult").value=`PERFIL WHATSAPP BUSINESS\nNome: ${n}\nCategoria: ${modal.querySelector("#waCategory").value}\nDescrição: ${modal.querySelector("#waDescription").value}\nHorário: ${modal.querySelector("#waHours").value}\nEndereço: ${modal.querySelector("#waAddress").value}\n\nSAUDAÇÃO\n${g}\n\nAUSÊNCIA\n${a}\n\nENCERRAMENTO\n${c}\n\nRESPOSTA RÁPIDA\n${q}\n\nMENU\n${opts.map((x,i)=>`${i+1}️⃣ ${x}`).join("\n")}`};if(key==="photos"){const input=modal.querySelector("#photoInput"),grid=modal.querySelector("#photoPreview");modal.querySelector("[data-photo-upload]").onclick=()=>input.click();input.onchange=()=>{grid.innerHTML="";[...input.files].forEach(f=>{const u=URL.createObjectURL(f);const img=document.createElement("img");img.src=u;img.dataset.src=u;const rd=new FileReader();rd.onload=()=>img.dataset.dataUrl=rd.result;rd.readAsDataURL(f);grid.appendChild(img)})};modal.querySelector("[data-photo-apply]").onclick=()=>{grid.querySelectorAll("img").forEach(i=>{const r=+modal.querySelector("#photoRadius").value;i.style.borderRadius=r+"px";i.style.aspectRatio=modal.querySelector("#photoFormat").value==="square"?"1/1":modal.querySelector("#photoFormat").value==="story"?"9/16":modal.querySelector("#photoFormat").value==="banner"?"16/9":"auto";i.style.objectFit="cover"})}}if(key==="catalog")renderCatalogRows(modal,p);modal.querySelector("[data-add-catalog]")?.addEventListener("click",()=>addCatalogRow(modal));modal.querySelector("[data-save-catalog]")?.addEventListener("click",()=>{const items=[...modal.querySelectorAll(".catalog-row")].map(r=>({name:r.querySelector("[data-c-name]").value,cat:r.querySelector("[data-c-cat]").value,price:r.querySelector("[data-c-price]").value,desc:r.querySelector("[data-c-desc]").value,img:r.querySelector("[data-c-img]").value}));if(p){p.items=items;ensureBusinessData(p);save();setStatus("Catálogo salvo e integrado ao projeto.")}const id=saved?.id||crypto.randomUUID();saveServiceProject({id,module:key,name:`${p?.name||saved?.name||"Meu negócio"} · ${SERVICE_MODULES[key].name}`,businessId:p?.id||saved?.businessId||null,createdAt:saved?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),data:{catalogItems:items}});modal.remove();renderServiceCentral()});modal.querySelector("[data-save-service]")?.addEventListener("click",()=>{const id=saved?.id||crypto.randomUUID();saveServiceProject({id,module:key,name:`${p?.name||"Meu negócio"} · ${SERVICE_MODULES[key].name}`,businessId:p?.id||saved?.businessId||null,createdAt:saved?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),data:(()=>{const d=collectToolData(modal,key);if(key==="photos")d.photoImages=[...modal.querySelectorAll("#photoPreview img")].map(i=>i.dataset.dataUrl).filter(Boolean);return d})()});modal.remove();renderServiceCentral();setStatus(saved?"Projeto atualizado na Central.":"Projeto salvo na Central.")});modal.querySelectorAll("[data-copy-result]").forEach(b=>b.onclick=()=>{copy(modal.querySelector("#"+b.dataset.copyResult).value);b.textContent="✓ Copiado";setTimeout(()=>b.textContent="📋 Copiar",900)});if(saved){hydrateServiceTool(modal,saved);if(key==="catalog")renderCatalogRows(modal,p);if(saved.data?.smResult&&modal.querySelector("#smResult"))modal.querySelector("#smResult").value=saved.data.smResult;if(saved.data?.waResult&&modal.querySelector("#waResult"))modal.querySelector("#waResult").value=saved.data.waResult}}
function hydrateServiceTool(modal,saved){if(!saved?.data)return;Object.entries(saved.data).forEach(([id,value])=>{const el=modal.querySelector("#"+CSS.escape(id));if(el&&el.type!=="file")el.value=value;});if(saved.module==="catalog"){} }
function collectToolData(m,key){const o={};m.querySelectorAll("input,textarea,select").forEach(x=>{if(x.id)o[x.id]=x.value});return o}
function renderCatalogRows(m,p){const mount=m.querySelector("#catalogRows");mount.innerHTML="";const arr=(p?.items||[]).slice(0,30);(arr.length?arr:[{name:"",cat:"",price:"",desc:"",img:""}]).forEach(x=>addCatalogRow(m,x))}
function addCatalogRow(m,x={name:"",cat:"",price:"",desc:"",img:""}){const mount=m.querySelector("#catalogRows"),row=document.createElement("div");row.className="catalog-row";row.innerHTML=`<input data-c-name placeholder="Nome" value="${esc(x.name||"")}"><input data-c-cat placeholder="Categoria" value="${esc(x.cat||"")}"><input data-c-price placeholder="Preço" value="${esc(x.price||"")}"><input data-c-desc placeholder="Descrição" value="${esc(x.desc||"")}"><input data-c-img placeholder="URL da imagem (opcional)" value="${esc(x.img||"")}"><button class="secondary" type="button">×</button>`;row.querySelector("button").onclick=()=>row.remove();mount.appendChild(row)}
function slug(s){return String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}
/* ---------- Editor: criador + Designer + ADM (mesmo painel) ---------- */
const getP=(o,path)=>path.split(".").reduce((a,k)=>a==null?a:a[k],o);
function setP(o,path,v){const ks=path.split(".");const l=ks.pop();ks.reduce((a,k)=>a[k],o)[l]=v}
const inp=(path,label,type="text",ph="")=>`<label>${label}<input type="${type}" data-p="${path}" placeholder="${esc(ph)}" value="${esc(getP(ed,path)||"")}"></label>`;
const sel=(path,label,opts)=>`<label>${label}<select data-p="${path}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(getP(ed,path))===v?"selected":""}>${esc(t)}</option>`).join("")}</select></label>`;
const mini=(path,ph)=>`<input data-p="${path}" placeholder="${ph}" value="${esc(getP(ed,path)||"")}">`;
function openEditor(p,mode){ed=JSON.parse(JSON.stringify(p));edMode=mode;tab=mode==="adm"?"funcoes":"dados";$("edTitle").textContent=mode==="adm"?"ADM — "+p.name:mode==="create"?"Criar site — "+p.name:"Editar — "+p.name;renderTab();$("editorDialog").showModal()}
function demoLinkFor(p){
 const sale=sales.find(s=>String(s.platformId||s.businessId)===String(p.id)||s.name===p.name);
 return sale&&sale.id ? `${location.origin}/demo/${encodeURIComponent(sale.id)}` : "";
}
function publicLinkFor(p){
 const demo=demoLinkFor(p);
 return demo || shareLink(p,"site").url;
}
function admHeader(){const demo=demoLinkFor(ed);const pub=publicLinkFor(ed);return `<div class="adm-top"><div><span class="eyebrow-ui">🔐 ADM V9</span><strong>${esc(ed.name)}</strong><small>Edite e publique o site do cliente.</small></div><div class="adm-links">${demo?`<a class="primary" href="${esc(demo)}" target="_blank">👁️ Abrir demonstração</a><button type="button" data-act="send-demo">📨 Enviar ao cliente</button>`:`<a class="primary" href="${esc(pub)}" target="_blank">🌐 Abrir site público</a>`}<button type="button" data-act="copy-public">📋 Copiar ${demo?"link da demonstração":"link público"}</button></div></div>`}
function renderTab(){const T=TPL[tplKey(ed.type)];$("tabs").innerHTML=[["dados","① Informações"],["funcoes","② Funções"],["conteudo","③ Conteúdo"],["design","④ Visual"],["previa","⑤ Prévia"]].map(([k,v])=>`<button type="button" data-act="tab" data-v="${k}" class="${k===tab?"active":""}">${v}</button>`).join("");$("edBody").innerHTML=(edMode==="adm"?admHeader():"")+({dados:tabDados,funcoes:tabFuncoes,conteudo:tabConteudo,design:tabDesign,previa:tabPrevia})[tab]();if(tab==="previa")drawFrame()}
function tabDados(){return`<div class="creator-intro"><div><span class="eyebrow-ui">CRIADOR V9</span><h3>Monte o site de ${esc(ed.name||"seu negócio")}</h3><p>O Radar gera uma primeira versão visual e conteúdo sugerido. Confirme tudo antes de publicar.</p></div><button type="button" class="primary" data-act="auto">✨ Gerar automaticamente</button></div><h4>1. Nível do site</h4><div class="level-grid">${Object.entries(LEVELS).map(([k,v])=>`<label class="level-card ${ed.level===k?"selected":""}"><input type="radio" name="site-level" data-p="level" value="${k}" ${ed.level===k?"checked":""}><strong>${v.name}</strong><span>${v.desc}</span></label>`).join("")}</div><h4>2. Informações</h4><div class="admin-grid">${sel("type","Tipo",Object.entries(labels))}${inp("name","Nome")}${inp("title","Título principal")}${inp("phone","Telefone")}${inp("whatsapp","WhatsApp")}${inp("instagram","Instagram")}</div>${inp("address","Endereço")}<label>Descrição<textarea data-p="description" rows="3">${esc(ed.description||"")}</textarea></label>`}
function tabFuncoes(){ensureBusinessData(ed);let h='<div class="creator-intro"><div><span class="eyebrow-ui">V11 · MOTOR DO NEGÓCIO</span><h3>Funções de '+esc(labels[ed.type]||"estabelecimento")+'</h3><p>O Radar escolheu módulos de acordo com o tipo de negócio. Ative ou desative o que realmente existe no estabelecimento.</p></div><button type="button" class="primary" data-act="auto-functions">✨ Reaplicar funções do tipo</button></div><div class="feature-grid">';(ed.modules||[]).forEach(function(m,i){h+='<label class="feature-card '+(m.on?"selected":"")+'"><div><strong>'+esc(MODULE_LABELS[m.k]||m.k)+'</strong><span>'+esc(FEATURE_DESCS[m.k]||"Função configurável.")+'</span></div><input type="checkbox" data-module="'+i+'" '+(m.on?"checked":"")+'></label>'});h+='</div>';if(moduleOn(ed,"booking")||moduleOn(ed,"reservations")||moduleOn(ed,"orders"))h+='<div class="suggestion-note"><b>Automação V11:</b> os formulários públicos montam a mensagem e abrem o WhatsApp. Isso já funciona sem servidor; confirmação de horário/reserva continua dependendo do estabelecimento.</div>';const addRows=function(key,fields,label,addLabel){if(!moduleOn(ed,key))return"";let out='<h4>'+label+'</h4>';const maps={staff:[["name","Nome"],["role","Função"],["specialty","Especialidade"]],services:[["name","Serviço"],["price","Preço"],["duration","Duração"],["desc","Descrição"]],plans:[["name","Plano"],["price","Preço"],["desc","Descrição"]],classes:[["name","Modalidade"],["days","Dias"],["time","Horário"]],rooms:[["name","Acomodação"],["price","Diária"],["desc","Descrição"]],specialties:[["name","Especialidade"],["desc","Descrição"]]};(ed[fields]||[]).forEach(function(x,i){out+='<div class="row">';(maps[fields]||[]).forEach(function(f){out+=mini(fields+'.'+i+'.'+f[0],f[1])});out+='<button type="button" data-act="del" data-l="'+fields+'" data-i="'+i+'">🗑️</button></div>'});out+='<button type="button" data-act="add" data-l="'+fields+'">➕ '+addLabel+'</button>';return out};h+=addRows("staff","staff","Profissionais","Adicionar profissional");h+=addRows("services","services","Serviços","Adicionar serviço");h+=addRows("plans","plans","Planos","Adicionar plano");h+=addRows("classes","classes","Aulas / horários","Adicionar aula");h+=addRows("rooms","rooms","Acomodações","Adicionar acomodação");h+=addRows("specialties","specialties","Especialidades","Adicionar especialidade");return h;}
