function tabDesign(){ensureDesignProposals(ed);const roles=imageRoles(ed.type);return `<div class="design-intro"><span class="eyebrow-ui">④ DESIGNER V14</span><h3>Designer original preservado + 3 propostas</h3><p>As funções antigas continuam. Escolha uma proposta e ajuste quatro controles que mudam a prévia de verdade.</p></div><div class="design-proposal-grid">${ed.designProposals.map((d,di)=>`<article class="design-proposal ${ed.selectedDesign===di?'selected':''}"><div class="proposal-head"><div><strong>${esc(d.name)}</strong><span>4 imagens · ${esc(roles.join(' · '))}</span></div><button type="button" class="${ed.selectedDesign===di?'primary':''}" data-act="select-design" data-di="${di}">${ed.selectedDesign===di?'✓ Selecionado':'Usar este design'}</button></div><div class="proposal-controls"><label>Tipografia<select data-design-control="font" data-di="${di}">${FONTS.map(f=>`<option value="${esc(f)}" ${d.font===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label><label>Formato das imagens<select data-design-control="shape" data-di="${di}">${[['round','Arredondado'],['square','Quadrado'],['pill','Pílula']].map(([v,t])=>`<option value="${v}" ${d.shape===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Estrutura<select data-design-control="hero" data-di="${di}">${Object.entries(LAYOUTS).map(([v,t])=>`<option value="${v}" ${d.hero===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Estilo<select data-design-control="style" data-di="${di}">${Object.entries(VISUAL_STYLES).map(([v,t])=>`<option value="${v}" ${d.visualStyle===v?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div class="design-images">${d.images.map((im,slot)=>`<label class="design-slot"><span>${slot+1}. ${esc(roles[slot])}</span><select data-design-image="${slot}" data-di="${di}">${galleryOptions(im)}</select>${im?`<img src="${esc(im)}" alt="">`:'<div class="image-placeholder">Sem imagem</div>'}</label>`).join('')}</div></article>`).join('')}</div><div class="design-gallery-note"><b>🖼️ Galeria:</b> cada quadro pode receber uma imagem da galeria. As propostas usam conjuntos/ordens diferentes quando existem imagens suficientes.</div><details><summary>⚙️ Controles originais avançados</summary><div class="style-grid">${Object.entries(VISUAL_STYLES).map(([id,v])=>`<button type="button" data-act="style" data-v="${id}" class="style-card ${ed.visualStyle===id?'selected':''}"><strong>${v.name}</strong><span>${v.desc}</span></button>`).join('')}</div><div class="admin-grid">${sel("layoutVariant","Hero / composição",Object.entries(LAYOUTS))}${sel("density","Ritmo",[["comfortable","Confortável"],["compact","Compacto"]])}${sel("btn","Botões",[["pill","Arredondados"],["round","Suaves"],["square","Quadrados"]])}${sel("font","Fonte",FONTS.map(f=>[f,f]))}${sel("dark","Tema",[["false","Claro"],["true","Escuro"]])}${inp("c1","Cor principal","color")}${inp("c2","Cor secundária","color")}</div></details><h4>Galeria do projeto</h4>${ed.gallery.map((g,i)=>`<div class="row two"><input data-p="gallery.${i}" placeholder="URL da imagem" value="${g.startsWith('data:')?'(imagem enviada)':esc(g)}" ${g.startsWith('data:')?'readonly':''}><button type="button" data-act="del" data-l="gallery" data-i="${i}">🗑️</button></div>`).join('')}<div class="actions"><button type="button" data-act="add" data-l="gallery">➕ Adicionar imagem</button><label class="secondary" style="margin:0">📷 Enviar imagem<input type="file" accept="image/*" data-file="gallery.new" hidden></label><button type="button" data-act="variant">🔄 Gerar outra versão</button><button type="button" data-act="images">🖼️ Reorganizar imagens</button></div>`}
