function enc(p){return encodeURIComponent(btoa(unescape(encodeURIComponent(JSON.stringify(p)))))}
function dec(x){try{return JSON.parse(decodeURIComponent(escape(atob(decodeURIComponent(x)))))}catch{return null}}
function shareLink(p,param){let n=0;const q=JSON.parse(JSON.stringify(p)),cut=s=>(s&&s.startsWith("data:"))?(n++,""):s;q.banner=cut(q.banner);q.gallery=(q.gallery||[]).map(cut).filter(Boolean);q.items=(q.items||[]).map(i=>({...i,img:cut(i.img)}));q.designImages=(q.designImages||[]).map(cut).filter(Boolean);(q.designProposals||[]).forEach(d=>d.images=(d.images||[]).map(cut));["staff","services","rooms","specialties"].forEach(k=>{if(Array.isArray(q[k]))q[k]=q[k].map(x=>({...x,img:cut(x.img)}))});return{url:location.origin+location.pathname+"?"+param+"="+enc(q),stripped:n}}
async function sendDemo(id){const p=platforms.find(x=>String(x.id)===String(id));if(!p){alert("Salve a demonstração antes de enviar.");return}let sale=sales.find(s=>String(s.platformId||s.businessId)===String(p.id)||s.name===p.name);if(!sale){sale={id:crypto.randomUUID(),name:p.name,type:p.type,phone:p.phone,whatsapp:p.whatsapp,stage:"demo",createdAt:new Date().toISOString(),service:"Site profissional",price:0,paymentStatus:"pending"};sales.push(sale)}sale.platformId=p.id;sale.businessId=p.id;sale.name=p.name;sale.type=p.type;sale.phone=sale.phone||p.phone;sale.whatsapp=sale.whatsapp||p.whatsapp;sale.stage="preview";sale.demoSentAt=new Date().toISOString();sale.demoViewedAt=null;sale.approvedAt=null;sale.publishedUrl=`${location.origin}/demo/${encodeURIComponent(sale.id)}`;sale.updatedAt=new Date().toISOString();saveSales();const url=sale.publishedUrl;let number=phoneDigits(sale.whatsapp||sale.phone||"");if(number.length===10||number.length===11)number="55"+number;const message=`Olá! Preparei uma demonstração personalizada para ${p.name}. Você pode visualizar o site neste link: ${url}\n\nQuando puder, veja a proposta e me diga o que achou. O botão de aprovação fica na própria página.`;let popup=null;if(number)popup=window.open("about:blank","_blank");const saved=await persistServerState();copy(url);if(number){const waUrl=`https://wa.me/${number}?text=${encodeURIComponent(message)}`;if(popup)popup.location.href=waUrl;else location.href=waUrl;if(popup)alert("A demonstração foi salva e o WhatsApp foi aberto com a mensagem e o link do site criado. Confira a conversa e toque em Enviar.");if(!saved)console.warn("O servidor não confirmou a persistência da demonstração.")}else{if(popup)popup.close();alert("Não há telefone/WhatsApp registrado para este cliente. "+(saved?"O link da demonstração foi copiado.":"Atenção: o servidor não confirmou o salvamento.")+"\n\nLink da demonstração: "+url+"\n\nMensagem sugerida:\n"+message)}renderSalesPipeline()}
async function refreshDemoStatus(id){try{const r=await fetch(`/api/demo/${encodeURIComponent(id)}`);const d=await r.json();if(!r.ok)throw new Error(d.error||"Não foi possível consultar o servidor.");const i=sales.findIndex(s=>String(s.id)===String(id));if(i>=0){sales[i]={...sales[i],...d.sale};saveSales()}alert(`Demonstração: ${d.sale.demoViewedAt?"visualizada":"ainda não visualizada"}. ${d.sale.approvedAt?"Cliente aprovou.":"Aprovação ainda pendente."}`)}catch(e){alert("Não foi possível atualizar agora. Verifique se o backend está publicado e tente novamente.")}}
function copy(t){if(navigator.clipboard)navigator.clipboard.writeText(t).catch(()=>{})}
function publish(id){const p=platforms.find(x=>x.id===id);if(!p)return;const sale=sales.find(s=>String(s.businessId)===String(p.id)||s.name===p.name);if(!p.published){p.published=true;save()}if(sale){sale.stage="published";sale.publishedUrl=shareLink(p,"site").url;sale.updatedAt=new Date().toISOString();saveSales()}const{url,stripped}=shareLink(p,"site");copy(url);
 alert("Plataforma publicada. Link copiado (quando o navegador permite):\n\n"+url+(stripped?`\n\nAtenção: ${stripped} imagem(ns) enviada(s) do computador não cabem no link. Use URLs de imagem ou “Baixar HTML” para levar tudo.`:"")+(url.length>8000?"\n\nO link ficou longo; se algum app cortar, use “Baixar HTML”.":""))}
function openPreview(id){const p=platforms.find(x=>x.id===id);if(!p)return;previewId=id;const sale=sales.find(s=>String(s.businessId)===String(p.id)||s.name===p.name);if(sale&&stageIndex(sale.stage)<stageIndex("preview"))advanceSale(sale.id,"preview");drawPreview();$("previewDialog").showModal()}
