function saveProspectionLocation(){if(here)localStorage.setItem("radarProspectionLocationV14",JSON.stringify({...here,savedAt:new Date().toISOString()}))}
function regionCandidates(lat,lon){return [{name:"Região próxima",km:5},{name:"Região ampliada",km:10},{name:"Região de oportunidade",km:15},{name:"Região comercial",km:20}].map((r,i)=>({...r,lat:lat+[0.045,-0.06,0.075,-0.09][i],lon:lon+[0.05,0.07,-0.06,-0.1][i]}))}
async function scanOpportunityRegions(){if(!here)return;setStatus("Procurando regiões mais promissoras...");const out=[];for(const r of regionCandidates(here.lat,here.lon)){try{const d=await queryServers(overpassQuery({lat:r.lat,lon:r.lon},Math.min(5000,r.km*1000),"all"));const arr=(d.elements||[]).map((e,i)=>parseBusiness(e,i,{lat:r.lat,lon:r.lon})).filter(isValid),high=arr.filter(x=>analyze(x).score>=2).length;out.push({...r,count:arr.length,high,score:Math.min(99,45+Math.min(30,arr.length)+Math.min(24,high*2))})}catch{}}regionOpps=out.sort((a,b)=>b.score-a.score);render();setStatus("Localização salva. Regiões com maior potencial foram calculadas.")}
function renderRegions(){const mount=$("regionMount");if(!mount)return;if(!here){mount.innerHTML="";return}if(!regionOpps.length){mount.innerHTML=`<section class="panel region-panel"><div class="section-head"><h2>📍 Prospecção por região</h2><p>Sua localização está salva como referência. Encontre áreas mais distantes com maior potencial comercial.</p></div><button id="scanRegions" class="primary">🔥 Encontrar regiões com mais chances de negócio</button></section>`;return}mount.innerHTML=`<section class="panel region-panel"><div class="section-head"><h2>🔥 Regiões com maior potencial</h2><p>O Radar prioriza concentração de negócios e sinais de oportunidade, não apenas distância.</p></div><div class="region-grid">${regionOpps.slice(0,4).map(r=>`<article class="region-card"><span>~${r.km} km</span><h3>${esc(r.name)}</h3><strong>${r.score}/100</strong><p>${r.count} negócios válidos · ${r.high} com sinais de oportunidade</p><button class="secondary" data-region-lat="${r.lat}" data-region-lon="${r.lon}" data-region-name="${esc(r.name)}">Pesquisar nesta região</button></article>`).join("")}</div></section>`}
